function supported_languages(): array {
    return lang_data()['languages'];
}

function normalize_language_code(?string $code): string {
    $code = strtolower(trim((string)$code));
    return array_key_exists($code, supported_languages()) ? $code : 'en';
}

function current_language_code(): string {
    if (session_status() === PHP_SESSION_NONE) {
        security_start_session();
    }

    return normalize_language_code($_SESSION['language_code'] ?? 'en');
}

function set_current_language_code(string $code): void {
    if (session_status() === PHP_SESSION_NONE) {
        security_start_session();
    }

    $_SESSION['language_code'] = normalize_language_code($code);
}

function get_user_language(mysqli $conn, int $userId): string {
    if ($userId <= 0) {
        return current_language_code();
    }

    $stmt = $conn->prepare("SELECT language_code FROM language_preferences WHERE user_id = ? LIMIT 1");
    if (!$stmt) {
        return current_language_code();
    }

    $stmt->bind_param('i', $userId);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();

    $language = normalize_language_code($row['language_code'] ?? 'en');
    set_current_language_code($language);

    return $language;
}

function set_user_language(mysqli $conn, int $userId, string $languageCode): string {
    $languageCode = normalize_language_code($languageCode);

    $stmt = $conn->prepare("
        INSERT INTO language_preferences (user_id, language_code)
        VALUES (?, ?)
        ON DUPLICATE KEY UPDATE language_code = VALUES(language_code)
    ");
    $stmt->bind_param('is', $userId, $languageCode);
    $stmt->execute();

    set_current_language_code($languageCode);
    return $languageCode;
}

function language_options(?string $selected = null): string {
    $selected = normalize_language_code($selected ?? current_language_code());

    $html = '';
    foreach (supported_languages() as $code => $label) {
        $isSelected = $selected === $code ? ' selected' : '';
        $html .= '<option value="' . htmlspecialchars($code, ENT_QUOTES, 'UTF-8') . '"' . $isSelected . '>' . htmlspecialchars($label, ENT_QUOTES, 'UTF-8') . '</option>';
    }

    return $html;
}


