function translation_map(string $type = 'ui', ?string $languageCode = null): array {
    static $cache = [];

    $languageCode = normalize_language_code($languageCode ?? current_language_code());
    $cacheKey = $type . ':' . $languageCode;

    if (isset($cache[$cacheKey])) {
        return $cache[$cacheKey];
    }

    if ($languageCode === 'en') {
        return $cache[$cacheKey] = [];
    }

    $map = lang_data()[$type][$languageCode] ?? [];

   
    $featureSources = [
        'rating_translation_overrides',
        'review_translation_additions',
        'wishlist_translation_additions',
        'complaint_translation_additions',
        'admin_statistics_translation_additions',
        'hint_translation_additions',
        'address_field_translation_additions',
        'complaint_resolution_translation_additions',
        'seller_verification_translation_additions',
        'kyc_clean_translation_additions',
        'auth_translation_additions',
    ];

    foreach ($featureSources as $source) {
        $featureMap = $source()[$type][$languageCode] ?? [];
        if ($featureMap) {
            $map = $featureMap + $map;
        }
    }

    return $cache[$cacheKey] = $map;
}

function translate_key(string $text, string $type = 'ui', ?string $languageCode = null): string {
    if ($text === '') {
        return $text;
    }

    $dictionary = translation_map($type, $languageCode);
    return $dictionary[$text] ?? $text;
}

function t(string $text): string {
    return translate_key($text, 'ui');
}

function translate_template_fragment(string $text, array $dictionary): string {
    if ($text === '' || trim($text) === '') {
        return $text;
    }

    $leading = '';
    $trailing = '';
    $inner = $text;

    if (preg_match('/^(\s*)(.*?)(\s*)$/su', $text, $matches)) {
        $leading = $matches[1];
        $inner = $matches[2];
        $trailing = $matches[3];
    }

    if ($inner === '') {
        return $text;
    }

    if (isset($dictionary[$inner])) {
        return $leading . $dictionary[$inner] . $trailing;
    }

    $normalizedInner = preg_replace('/\s+/u', ' ', trim($inner));
    if ($normalizedInner !== null && isset($dictionary[$normalizedInner])) {
        return $leading . $dictionary[$normalizedInner] . $trailing;
    }

    $prefixKeys = [
        'Welcome back,',
        'Order #',
        'Sale Order #',
    ];

    foreach ($prefixKeys as $prefix) {
        if (isset($dictionary[$prefix]) && str_starts_with($inner, $prefix)) {
            return $leading . $dictionary[$prefix] . substr($inner, strlen($prefix)) . $trailing;
        }
    }

    return $text;
}

function translate_template_tag_attributes(string $tag, array $dictionary): string {
    $translatableAttributes = 'placeholder|title|aria-label|alt|data-show-more|data-show-less|data-empty-text|data-delivery-label|data-pickup-label|data-confirm';

    return preg_replace_callback(
        "/\\s(" . $translatableAttributes . ")=([\\'\\\"])(.*?)\\2/su",
        static function (array $matches) use ($dictionary): string {
            return ' ' . $matches[1] . '=' . $matches[2] . translate_template_fragment($matches[3], $dictionary) . $matches[2];
        },
        $tag
    );
}

function tr_template(string $html): string {
    $dictionary = translation_map('ui');

    if (!$dictionary) {
        return $html;
    }

    uksort($dictionary, static fn($a, $b) => strlen($b) <=> strlen($a));

    $protectedBlocks = [];
    $html = preg_replace_callback(
        '/<([a-zA-Z][a-zA-Z0-9]*)\b([^>]*\sdata-no-translate\b[^>]*)>.*?<\/\1>/su',
        static function (array $matches) use (&$protectedBlocks): string {
            $key = '___NO_TRANSLATE_BLOCK_' . count($protectedBlocks) . '___';
            $protectedBlocks[$key] = $matches[0];
            return $key;
        },
        $html
    );

    $parts = preg_split('/(<[^>]+>)/u', $html, -1, PREG_SPLIT_DELIM_CAPTURE);
    if ($parts === false) {
        return $html;
    }

    foreach ($parts as $index => $part) {
        if ($part === '') {
            continue;
        }

        if ($part[0] === '<') {
            $parts[$index] = translate_template_tag_attributes($part, $dictionary);
        } else {
            $parts[$index] = translate_template_fragment($part, $dictionary);
        }
    }

    $translated = implode('', $parts);

    if ($protectedBlocks) {
        $translated = strtr($translated, $protectedBlocks);
    }

    return $translated;
}

function translate_dynamic_text(?string $text, ?string $targetLanguage = null): string {
    $text = (string)($text ?? '');

    if ($text === '') {
        return $text;
    }

    $translated = translate_key($text, 'fixed', $targetLanguage);

    if ($translated !== $text) {
        return $translated;
    }

    return translate_key($text, 'ui', $targetLanguage);
}

